openLink = (url: string) => {
    void context.executeCommand('command:quirky.tasks/open-link', { url }).catch((cause) => setError(errorMessage(cause)))
  }

changeRepoSource = async (preference: 'origin' | 'upstream') => {
    const repo = selectedRepos[0]
    const origin = object(issueSource.origin)
    const sourceIdentity = preference === 'origin' ? origin : issueSource.candidates?.find((entry) => {
      const candidate = object(entry)
      if (!candidate || !origin) return false
      return `${String(candidate.host).toLowerCase()}/${String(candidate.owner).toLowerCase()}/${String(candidate.repo).toLowerCase()}` !== `${String(origin.host).toLowerCase()}/${String(origin.owner).toLowerCase()}/${String(origin.repo).toLowerCase()}`
    })
    const candidate = object(sourceIdentity)
    if (!repo || !candidate || typeof candidate.host !== 'string' || typeof candidate.owner !== 'string' || typeof candidate.repo !== 'string') return
    const target: ItemTarget = {
      worktree: repo.worktree,
      kind: 'issue',
      number: 1,
      url: `https://${candidate.host}/${candidate.owner}/${candidate.repo}/issues/1`
    }
    invalidateViewGeneration()
    try {
      await context.call('quirky.tasks/row', { target, action: 'issueSource', preference })
      invalidateViewGeneration()
      setOptimistic(clearIssueRetentions)
      await loadList(true)
    } catch (cause) {
      invalidateViewGeneration()
      await loadList(true)
      setError(errorMessage(cause))
    }
  }

onRow = (item: ListItem) => {
    if (listScroll.current) place.setScrollTop('expanded', currentKey, listScroll.current.scrollTop)
    void navigate({ detail: rowTarget(item) })
  }

navigate = async (patch: Record<string, unknown>): Promise<TasksState | null> => {
    try {
      const next = parseTasksState(await context.call('quirky.tasks/navigate', patch))
      if (!next) throw new Error('Invalid Tasks state from daemon')
      adopt(next)
      return next
    } catch (cause) {
      setError(errorMessage(cause))
      return null
    }
  }

loadList = async (noCache = false, deliberate = false) => {
    const key = currentKey
    if (navigation.mode === 'projects') return
    const generation = ++fetchGeneration.current
    const ownerGeneration = viewGeneration.current
    const ownsRequest = () => generation === fetchGeneration.current && latestKey.current === key && viewGeneration.current === ownerGeneration
    if (deliberate) {
      setOptimistic((previous) => Object.fromEntries(Object.entries(previous).filter(([, pending]) =>
        !pending.keepVisible && !(pending.item.kind === 'issue' && pending.retention !== undefined)
      )))
      checkTriggered.current.clear()
      setChecks({})
    }
    setLoading(true)
    if (noCache) setRefreshing(true)
    try {
      const loaded = await fetchList(noCache)
      if (!ownsRequest()) return
      setResult(loaded)
      setResultKey(key)
      setError(null)
      setListError(null)
    } catch (cause) {
      if (!ownsRequest()) return
      setListError(errorMessage(cause))
      if (focusOwner.current === key) wantsFocus.current = false
      if (resultKeyRef.current !== key) setResult(null)
    } finally {
      if (ownsRequest()) {
        setLoading(false)
        setRefreshing(false)
      }
    }
  }

fetchList = async (noCache: boolean): Promise<ListData> => {
    const value = await context.call('quirky.tasks/list', {
      mode,
      repoIds: repoSelectionForList.current.repoIds,
      query: navigation.query,
      page: navigation.page,
      ...(noCache ? { noCache: true } : {})
    })
    const parsed = parseListResult(value)
    if (!parsed) throw new Error('The Tasks list API returned an invalid result.')
    return parsed
  }

requestControl = async (control: ListControl, open: boolean) => {
    try {
      await dispatchListControl(context, { control, open })
    } catch (cause) {
      setError(errorMessage(cause))
    }
  }

export async function dispatchListControl(context: UiPluginContext, request: ListControlRequest): Promise<void> {
  const epoch = windowConnectionEpoch(context)
  const started = epoch.value
  const self = record(await context.call('ui.window.self', {}))
  if (epoch.value !== started) throw new Error('The UI connection changed before the action could be sent. Try again.')
  const connId = self?.connId
  if (typeof connId !== 'number' || !Number.isSafeInteger(connId) || connId < 1) {
    throw new Error('The daemon did not identify this UI connection.')
  }
  const descriptor = listControlDescriptor(request)
  await context.call('ui.window.command.run', { connId, id: descriptor.command, args: descriptor.args })
}

export function listControlDescriptor(request: ListControlRequest): { command: typeof LIST_CONTROL_COMMAND; args: ListControlRequest } {
  return { command: LIST_CONTROL_COMMAND, args: request }
}

commitSearch = (value: string) => {
    committed(searchLane)
    setSearchDraft(value)
    clearTimeout(searchTimer.current)
    searchTimer.current = undefined
    let next: string
    try {
      next = queryForKind(value, kind)
    } catch (cause) {
      setError(errorMessage(cause))
      return
    }
    if (new TextEncoder().encode(next).byteLength > 8192) {
      setError('Search query exceeds the 8192-byte limit.')
      return
    }
    if (next !== expected(searchLane, navigation.query)) void sendSearch(next, { page: 1, scrollTop: 0 })
  }

sendSearch = async (query: string, patch: Record<string, unknown>) => {
    sending(searchLane, query)
    const reply = await navigate({ ...patch, query })
    settled(searchLane, reply)
    if (mounted.current) setSearchSettlement((value) => value + 1)
    return reply
  }

